import { describe, expect, it } from 'vitest'
import { mineProductionInsight, runStructuredQuery } from '../src/services/deepPrototypeMock'
import type { StructuredQueryInput } from '../src/types/deepPrototype'

const queryInput: StructuredQueryInput = {
  question: '查看惠州油区 2026 到 2028 年产量',
  metric: '产量',
  dimensions: ['油气田', '年份'],
  filters: { oil区: '惠州油区', 年份: [2026, 2027, 2028] },
  version: '规划 V3 草案',
  permission: { scope: '惠州油区', allowedMetrics: ['产量', '递减率'] },
}

describe('结构化数据智能问数', () => {
  it('成功问数返回识别条件、演示 SQL、表格图表和完整追溯信息', () => {
    const result = runStructuredQuery(queryInput)

    expect(result.status).toBe('success')
    expect(result.recognized).toEqual({
      metric: '产量',
      dimensions: ['油气田', '年份'],
      filters: { oil区: '惠州油区', 年份: [2026, 2027, 2028] },
      permissionScope: '惠州油区',
    })
    expect(result.sql).toContain('SELECT')
    expect(result.rows.length).toBeGreaterThan(0)
    expect(result.chart).not.toBeNull()
    expect(result.trace).toMatchObject({
      source: expect.any(String),
      version: '规划 V3 草案',
      scope: '惠州油区',
      reviewStatus: '待复核',
      mock: true,
    })
  })

  it('筛选范围无匹配时返回空结果和查询条件，不改成虚构数据', () => {
    const result = runStructuredQuery({
      ...queryInput,
      filters: { ...queryInput.filters, 油气田: '无匹配样例' },
    })

    expect(result.status).toBe('empty')
    expect(result.rows).toEqual([])
    expect(result.chart).toBeNull()
    expect(result.recognized.filters).toMatchObject({ 油气田: '无匹配样例' })
  })

  it('指标超出当前身份范围时返回权限受限且不生成 SQL', () => {
    const result = runStructuredQuery({
      ...queryInput,
      metric: '储量',
      permission: { scope: '惠州油区', allowedMetrics: ['产量'] },
    })

    expect(result.status).toBe('permission_denied')
    expect(result.sql).toBeUndefined()
    expect(result.rows).toEqual([])
    expect(result.message).toContain('权限')
  })

  it('本地 Mock 未支持的指标明确返回不支持，不套用相近指标', () => {
    const result = runStructuredQuery({
      ...queryInput,
      metric: '天气',
      permission: { scope: '惠州油区', allowedMetrics: ['天气'] },
    })

    expect(result.status).toBe('unsupported_metric')
    expect(result.recognized.metric).toBe('天气')
    expect(result.rows).toEqual([])
    expect(result.message).toContain('不支持')
  })
})

describe('开发生产规律智能挖掘', () => {
  it('历史数据充足时返回趋势、证据、摘要并标记需专家复核', () => {
    const result = mineProductionInsight({
      metric: '递减率',
      version: '历史生产 V2',
      scope: '惠州油区',
      history: [
        { period: '2023', value: 0.08, sourceRecordId: 'history-2023' },
        { period: '2024', value: 0.09, sourceRecordId: 'history-2024' },
        { period: '2025', value: 0.14, sourceRecordId: 'history-2025' },
        { period: '2026', value: 0.1, sourceRecordId: 'history-2026' },
      ],
