    expect(result.status).toBe('success')
    expect(result.trend).toHaveLength(4)
    expect(result.evidence.map((item) => item.sourceRecordId)).toEqual([
      'history-2023',
      'history-2024',
      'history-2025',
      'history-2026',
    ])
    expect(result.summary).not.toBe('')
    expect(result.trace.reviewStatus).toBe('需专家复核')
  })

  it('历史样本不足时返回不足状态且不编造规律摘要', () => {
