      metric: '采收率',
      version: '历史生产 V2',
      scope: '惠州油区',
      history: [{ period: '2026', value: 0.31, sourceRecordId: 'history-2026' }],
    })

    expect(result.status).toBe('insufficient_history')
    expect(result.anomalies).toEqual([])
    expect(result.summary).toContain('不足')
    expect(result.trace.reviewStatus).toBe('需专家复核')
  })
