import { describe, expect, it } from 'vitest'
import { classifyReserve, createClassificationReview } from '../src/services/deepPrototypeMock'
import type { ReserveClassificationInput } from '../src/types/deepPrototype'

const classificationInput: ReserveClassificationInput = {
  version: '内部储量 V2 草案',
  scope: 'A 在生产油气田',
  records: [
    {
      id: 'reserve-a1',
      oilfieldStatus: 'A 在生产油气田',
      reserveLevel: 'P1',
      commerciality: 'C1',
      difficultyType: '稠油',
    },
  ],
}

describe('难动用储量分级演示规则', () => {
  it('相同输入返回完全一致且可追溯的分级运行结果', () => {
    const first = classifyReserve(classificationInput)
    const second = classifyReserve(structuredClone(classificationInput))

    expect(first).toEqual(second)
    expect(first.status).toBe('completed')
    expect(first.run?.results[0]).toMatchObject({
      recordId: 'reserve-a1',
      code: 'AC1a',
      name: '稠油难动用探明',
    })
    expect(first.run?.trace).toMatchObject({
      source: '内部储量+未动用储量录入模板.xlsx',
      version: '内部储量 V2 草案',
      scope: 'A 在生产油气田',
      reviewStatus: '待复核',
      mock: true,
    })
  })

  it('来源字段缺失时返回阻断，不伪造分级结果', () => {
    const result = classifyReserve({
      ...classificationInput,
      records: [{ id: 'reserve-missing', oilfieldStatus: 'A 在生产油气田' }],
    })

    expect(result.status).toBe('blocked')
    expect(result.run).toBeUndefined()
    expect(result.blockers[0]).toMatchObject({
      recordId: 'reserve-missing',
      missingFields: expect.arrayContaining(['reserveLevel', 'commerciality', 'difficultyType']),
    })
  })

  it('人工改分级时形成包含改前改后、原因、复核人和调用留痕的草案', () => {
    const review = createClassificationReview({
      runId: 'classification-run-a1',
      recordId: 'reserve-a1',
      originalClassification: { code: 'AC1a', name: '稠油难动用探明' },
      revisedClassification: { code: 'AC1b', name: '“三低”难动用探明' },
      reviewer: '张三',
      reason: '现场资料补充后需改为“三低”类型，待专家确认',
      version: '内部储量 V2 草案',
      scope: 'A 在生产油气田',
    })

    expect(review).toMatchObject({
      runId: 'classification-run-a1',
      recordId: 'reserve-a1',
      originalClassification: { code: 'AC1a', name: '稠油难动用探明' },
      revisedClassification: { code: 'AC1b', name: '“三低”难动用探明' },
      reviewer: '张三',
      status: 'draft',
      trace: { reviewStatus: '待复核', mock: true },
    })
    expect(review.reason).not.toBe('')
  })
})

import { describe, expect, it } from 'vitest'
import { evaluateScheduleChange, simulateProductionProfile } from '../src/services/deepPrototypeMock'
import type { ProductionProfileInput, ScheduleEvaluationInput } from '../src/types/deepPrototype'

const profileInput: ProductionProfileInput = {
  version: '规划 V3 草案',
  scope: '惠州油区',
  oilfieldId: 'hz-26-1',
  method: '递减曲线法',
  startYear: 2026,
  baseAnnualProduction: 20,
  targetDeclineRate: 0.08,
  commissioningYear: 2027,
  wellCount: 3,
  workload: 12,
}

const scheduleInput: ScheduleEvaluationInput = {
  version: '规划 V3 草案',
  scope: '惠州油区',
  changes: [
    {
      projectId: 'hz-project-1',
      fromCommissioningYear: 2027,
      toCommissioningYear: 2028,
      workloadByYear: { 2027: 8, 2028: 4 },
      proposedWorkloadByYear: { 2027: 2, 2028: 10 },
    },
  ],
  capacityByYear: { 2027: 12, 2028: 12 },
}

describe('产量剖面演示计算', () => {
  it('递减目标变化会改变调整后曲线，并保留同一输入版本', () => {
    const baseline = simulateProductionProfile(profileInput)
    const adjusted = simulateProductionProfile({ ...profileInput, targetDeclineRate: 0.12 })

    expect(baseline.status).toBe('completed')
    expect(adjusted.status).toBe('completed')
    expect(adjusted.series).not.toEqual(baseline.series)
    expect(adjusted.impacts).toEqual(
      expect.arrayContaining([expect.objectContaining({ field: 'targetDeclineRate' })]),
    )
    expect(adjusted.trace).toMatchObject({ version: '规划 V3 草案', mock: true })
  })

  it('上下限互相矛盾时明确返回无解而不是伪造曲线', () => {
    const result = simulateProductionProfile({
      ...profileInput,
      constraints: { minimumAnnualProduction: 25, maximumAnnualProduction: 20 },
    })

    expect(result.status).toBe('no_solution')
    expect(result.reason).toContain('约束')
    expect(result.series).toEqual([])
    expect(result.trace.reviewStatus).toBe('待复核')
  })
})

describe('工作量排期联动', () => {
  it('投产时间变化会同时影响原年份和新年份的剖面差异', () => {
    const result = evaluateScheduleChange(scheduleInput)

    expect(result.affectedYears).toEqual(expect.arrayContaining([2027, 2028]))
    expect(result.profileDeltas.map((item) => item.year)).toEqual(expect.arrayContaining([2027, 2028]))
    expect(result.profileDeltas.every((item) => item.projectIds.includes('hz-project-1'))).toBe(true)
  })

  it('年度工作量变化会产生可见联动但不会修改输入对象', () => {
    const original = structuredClone(scheduleInput)
    const result = evaluateScheduleChange(scheduleInput)

    expect(result.status).toBe('linked')
    expect(result.profileDeltas.some((item) => item.delta !== 0)).toBe(true)
    expect(scheduleInput).toEqual(original)
    expect(result.trace).toMatchObject({ version: '规划 V3 草案', scope: '惠州油区', mock: true })
  })

  it('工作量超过年度资源容量时返回冲突年份和项目', () => {
    const result = evaluateScheduleChange({
      ...scheduleInput,
      capacityByYear: { 2027: 12, 2028: 8 },
    })

    expect(result.status).toBe('conflict')
    expect(result.conflicts).toEqual([
      expect.objectContaining({
        year: 2028,
        required: 10,
        capacity: 8,
        projectIds: ['hz-project-1'],
      }),
    ])
  })
})

