import { describe, expect, it } from 'vitest'
import { transitionPlanningTask } from '../src/services/deepPrototypeMock'
import type { PlanningTask, PlanningTaskEvent, PlanningTransitionResult } from '../src/types/deepPrototype'

const draftTask: PlanningTask = {
  id: 'planning-2027-annual',
  title: '2027 年度产量规划',
  type: 'annual',
  stage: 'draft',
  round: 1,
  participantScopes: ['惠州油区', '西江油区'],
  dueDate: '2026-09-30',
  version: '规划 V3 草案',
  progress: 0,
  blockers: [],
}

describe('规划任务状态流', () => {
  it('草稿不能越级直接提交复核，并保持原任务不变', () => {
    const result = transitionPlanningTask(draftTask, 'submit_review')

    expect(result.ok).toBe(false)
    expect(result.task).toEqual(draftTask)
    expect(result.error).toContain('draft')
  })

  it('发布、填报、校验、复核和归档按顺序可执行', () => {
    const events: PlanningTaskEvent[] = [
      'publish',
      'start_filling',
      'submit_validation',
      'submit_review',
      'archive',
    ]
    const stages = ['published', 'filling', 'validating', 'reviewing', 'archived']

    const results = events.reduce<PlanningTransitionResult[]>((history, event) => {
      const currentTask = history.at(-1)?.task ?? draftTask
      return [...history, transitionPlanningTask(currentTask, event)]
    }, [])

    expect(results.every((result) => result.ok)).toBe(true)
    expect(results.map((result) => result.task.stage)).toEqual(stages)
  })

  it('只有复核中的任务可退回，退回后只能恢复填报', () => {
    const invalidReturn = transitionPlanningTask(draftTask, 'return')
    expect(invalidReturn.ok).toBe(false)

    const reviewingTask: PlanningTask = { ...draftTask, stage: 'reviewing', progress: 100 }
    const returned = transitionPlanningTask(reviewingTask, 'return')
    expect(returned).toMatchObject({ ok: true, task: { stage: 'returned' } })

    const invalidArchive = transitionPlanningTask(returned.task, 'archive')
    expect(invalidArchive.ok).toBe(false)

    const resumed = transitionPlanningTask(returned.task, 'resume_filling')
    expect(resumed).toMatchObject({ ok: true, task: { stage: 'filling' } })
  })
})

